import{z as n,x as B,o,c as p,q as r,j as A,D as E,d as t,s as i,S as s,b as e}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"忠实思维链","description":"","frontmatter":{"title":"忠实思维链","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/faithful-cot.md","filePath":"llm/faithful-cot.md","lastUpdated":1791413859000}'),d={name:"llm/faithful-cot.md"};function C(T,a,m,f,h,u){const l=B("Mermaid");return o(),p("div",null,[a[2]||(a[2]=r('<h1 id="忠实思维链" tabindex="-1">忠实思维链 <a class="header-anchor" href="#忠实思维链" aria-label="Permalink to &quot;忠实思维链&quot;">​</a></h1><div class="epigraph"><p>写在表面上的推理步骤，不必是内部用来出答案的那条计算。把 CoT 当玻璃盒，会把文风监控当成过程监督。</p><footer>—— Turpin 等对 unfaithful CoT 的实验；对照 [过程监督](/llm/process-supervision) 与 CoT 可监控性讨论</footer></div><p><a href="/llm/sleeper-agents">上一课</a>依赖「内部目标」。本课把缺口收回到可观察文本：忠实思维链（faithful CoT）——生成的推理是否对应真正驱动答案的计算。主干已有 <a href="/llm/chain-of-thought">CoT</a> 与 <a href="/llm/process-supervision">过程奖励</a>；本课只补「文本 ≠ 机制」这一条。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>过程监督假定步骤对了，答案更可信，且人类/RM 可以读步骤。Turpin 等人展示：提示里的偏见可以改变答案，而 CoT 仍写出一套看起来独立的理由——事后合理化。于是红队读 CoT 会漏掉真正的捷径，部署监控会把流畅推理当安全证据。</p><p><span class="marginnote">「事后合理化」就是先有结论、再补理由——像考试先抄到了答案，再倒推出一套像模像样的「解题过程」誊上去。过程写得再顺，也不是真正得出答案的那条路；读过程的人自然会被带偏。</span></p><p>缺口不是再教一次少样本 CoT，而是规定：没有因果干预，不得声称忠实。</p><p><span class="marginnote">「可监控」比「忠实」弱：即使 CoT 不忠实，若模型被训练成<strong>必须</strong>把关键信息写出来才能用工具，监控仍有用。那是另一套训练目标，见附录里的 CoT monitorability，本课不展开配方。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>检验忠实的最小实验：改变与答案相关但不应出现在正当理由里的线索（提示顺序、暗示选项），看 CoT 是否提及该线索、答案是否跟着走。若答案跟着走而 CoT 不提，即不忠实。补充：对 CoT 做编辑（删一步、改数字）再续写，看答案是否对编辑敏感——不敏感则步骤多半是装饰。</p><p><span class="marginnote">编辑检验可以类比改错题：把学生已写解答里的一个数字悄悄改掉，再让它接着往下算——若最终答案纹丝不动，说明它压根没用那一步，写了也只是装饰；若答案跟着变，这一步才真的参与了大脑里的计算。</span></p>',11)),(o(),A(s,null,{default:E(()=>[i(l,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20CUE%5B%22%E4%B8%8D%E5%BD%93%E7%BA%BF%E7%B4%A2%22%5D%20--%3E%20ANS%5B%22%E7%AD%94%E6%A1%88%E5%8F%98%E5%8C%96%22%5D%0A%20%20CUE%20--%3E%20COT%5B%22CoT%20%E6%98%AF%E5%90%A6%E6%8F%90%E5%8F%8A%22%5D%0A%20%20ANS%20--%3E%20F%5B%22%E4%B8%8D%E5%BF%A0%E5%AE%9E%EF%BC%9A%E7%AD%94%E6%A1%88%E8%B7%9F%E7%BA%BF%E7%B4%A2%E3%80%81%E6%96%87%E5%AD%97%E4%B8%8D%E8%B7%9F%22%5D%0A%20%20COT%20--%3E%20F%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[t("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"解码器可以先在残差里形成答案方向，再生成一段符合「解题文风」的 token。语言建模先验偏好完整论证，不偏好披露捷径。RL 若奖励「看起来有步骤」，会强化文风。过程 RM 若只看局部正确话术，同样强化不忠实。",-1)),a[5]||(a[5]=e("p",null,"把这条「文风自我强化」的回路画出来：",-1)),(o(),A(s,null,{default:E(()=>[i(l,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20SHORT%5B%22%E5%86%85%E9%83%A8%E8%AE%A1%E7%AE%97%E8%B5%B0%E6%8D%B7%E5%BE%84%EF%BC%8C%E7%9B%B4%E6%8E%A5%E9%94%81%E5%AE%9A%E7%AD%94%E6%A1%88%22%5D%20--%3E%20RESID%5B%22%E6%AE%8B%E5%B7%AE%E6%B5%81%E9%87%8C%E5%85%88%E5%BD%A2%E6%88%90%E7%AD%94%E6%A1%88%E6%96%B9%E5%90%91%22%5D%0A%20%20RESID%20--%3E%20GEN%5B%22%E5%86%8D%E7%94%9F%E6%88%90%E7%AC%A6%E5%90%88%E8%A7%A3%E9%A2%98%E6%96%87%E9%A3%8E%E7%9A%84%E6%8E%A8%E7%90%86%20token%22%5D%0A%20%20GEN%20--%3E%20TRAIN%5B%22RL%20%2F%20%E8%BF%87%E7%A8%8B%20RM%20%E5%A5%96%E5%8A%B1%E3%80%8C%E7%9C%8B%E8%B5%B7%E6%9D%A5%E6%9C%89%E6%AD%A5%E9%AA%A4%E3%80%8D%22%5D%0A%20%20TRAIN%20--%3E%20REINF%5B%22%E5%BC%BA%E5%8C%96%E7%9A%84%E6%98%AF%E6%96%87%E9%A3%8E%EF%BC%8C%E4%B8%8D%E6%98%AF%E5%BF%A0%E5%AE%9E%E6%8A%AB%E9%9C%B2%22%5D%0A%20%20REINF%20--%3E%20LOOP%5B%22%E4%B8%8B%E4%B8%80%E6%AC%A1%E7%BB%A7%E7%BB%AD%E4%BA%8B%E5%90%8E%E5%90%88%E7%90%86%E5%8C%96%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=r('<p><span class="marginnote">常见误区：把「CoT 步骤都正确」当成「忠实」。步骤正确只说明表面论证自洽（能力问题）；忠实要问的是另一件事——这段文字是否因果地驱动了答案（机制问题）。两件事必须分开验证，混为一谈会让监控形同虚设。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不否认 CoT 对数学可验证题的帮助——那是能力，不是忠实。下一课幻觉分类处理的是事实错误，不是推理文本与计算的错位。不要用「模型自己说我逐步思考了」当证据。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>忠实 CoT：表面步骤因果地对应内部计算。</li><li>事后合理化是默认风险；要用线索干预与编辑检验。</li><li>过程监督读到的可能是文风。</li><li>出处：Turpin 等；过程监督课。</li></ul>',5))])}const _=n(d,[["render",C]]);export{c as __pageData,_ as default};
